import { Object3D, PlaneGeometry, Mesh } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.imageUrl
 * @property {Object} atlas
 * @property {Object} atlas.region
 * @property {number} atlas.region.x
 * @property {number} atlas.region.y
 * @property {number} atlas.region.w
 * @property {number} atlas.region.h
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {Object} placement
 * @property {Array<number>} placement.position
 * @property {Array<number>} placement.rotation
 * @property {Array<number>} placement.scale
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>import('three').Texture} textureLoader
 * @property {Record<string, (obj:import('three').Object3D, params:any)=>void>} primitives
 */

/**
 * Creates a sprite node: a textured plane that always faces the camera.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
	// Root container
	const root = new Object3D();

	// Placement
	if (config.placement?.position) root.position.fromArray(config.placement.position);
	if (config.placement?.rotation) root.rotation.fromArray(config.placement.rotation);
	if (config.placement?.scale) root.scale.fromArray(config.placement.scale);

	// ------------------------------------------------------------
	// Geometry – sized to the atlas region’s aspect ratio
	// ------------------------------------------------------------
	const region = config.atlas?.region ?? { x: 0, y: 0, w: 512, h: 320 };
	const aspect = region.w / region.h;
	const planeWidth = aspect; // height = 1 unit
	const planeHeight = 1;
	const geometry = new PlaneGeometry(planeWidth, planeHeight);

	// ------------------------------------------------------------
	// Texture – load and apply UV offset / repeat for atlas region
	// ------------------------------------------------------------
	const tex = ctx.textureLoader(config.assets?.imageUrl ?? '');
	const imgW = tex.image?.width ?? region.w;
	const imgH = tex.image?.height ?? region.h;

	// UV offset (Three.js origin is lower‑left)
	tex.offset.set(region.x / imgW, 1 - (region.y + region.h) / imgH);
	tex.repeat.set(region.w / imgW, region.h / imgH);
	tex.needsUpdate = true;
	tex.minFilter = tex.magFilter = tex.generateMipmaps ? THREE.LinearMipmapLinearFilter : THREE.LinearFilter;

	// ------------------------------------------------------------
	// Material – Basic node material with the texture node
	// ------------------------------------------------------------
	const material = new MeshBasicNodeMaterial();
	material.map = texture(tex);
	material.transparent = true;
	material.depthTest = true;
	material.depthWrite = false;

	// ------------------------------------------------------------
	// Mesh – billboard toward camera each frame
	// ------------------------------------------------------------
	const mesh = new Mesh(geometry, material);
	mesh.onBeforeRender = (_, __, camera) => {
		mesh.quaternion.copy(camera.quaternion);
	};
	root.add(mesh);

	// ------------------------------------------------------------
	// Apply cinematic primitives if any
	// ------------------------------------------------------------
	if (Array.isArray(config.cinematicPrimitives)) {
		for (const prim of config.cinematicPrimitives) {
			const fn = ctx.primitives?.[prim.name];
			if (typeof fn === 'function') {
				fn(root, prim.params);
			}
		}
	}

	// ------------------------------------------------------------
	// User data – handlers container & cleanup routine
	// ------------------------------------------------------------
	root.userData.handlers = {};

	root.userData.cleanup = () => {
		geometry.dispose();
		material.dispose();
		// Do not dispose the texture here; it may be shared.
		gsap.killTweensOf(root);
	};

	return root;
}
